# -*- coding: utf-8 -*-
"""Lecture 26 vignette pool B -- Venous Disorders: deep vein thrombosis cases.

KEYS ARE WRITTEN SHORT ON PURPOSE -- detail lives in the explanation.

Patient vignettes (Set 2) with a varied lead-in (the lead-in decides the answer).
Carries the three priorities Shah stressed, by stem word: the Virchow triad,
the Wells criteria (score arithmetic checked item by item against slide 55:
travel is NOT an item; immobilization means bedridden after surgery or a
cast; a score of exactly 0 is never used) and the D-dimer versus ultrasound
decision (slide 56). Duration, setting, agents, reversal, filter and
thrombolysis follow slides 61-71. No dosing, no brand names.
"""
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from _cmse3_q import Q
from cms_e5l26_scope import *


def S(topic, io, q, opts, cite, slot):
    d = Q(topic, io, q, opts, cite); d["slot"] = slot; return d


def V(topic, io, q, opts, cite, slot, lead):
    d = S(topic, io, q, opts, cite, slot); d["lead"] = lead; return d


